const fs = require('fs');
const path = require('path');

// 1. Helper to write markdown files cleanly
function writeMd(filePath, title, category, tradition, intro, sections, anukramanikaLink = '../000_anukramanika.md') {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

  let text = `# ${title}\n\n`;
  text += `**विभाग:** ${category}  \n`;
  text += `**स्रोत / परंपरा:** ${tradition}  \n`;
  text += `**कॉपीराइट स्थिति:** १००% सार्वजनिक अधिकार क्षेत्र (Public Domain — सनातन ज्ञान धरोहर)  \n\n`;
  text += `[← मुख्य अनुक्रमणिका](${anukramanikaLink})\n\n---\n\n`;
  text += `## 📜 परिचय एवं शास्त्रीय महत्त्व\n${intro}\n\n---\n\n`;

  sections.forEach(s => {
    text += `## ${s.heading}\n${s.body}\n\n---\n\n`;
  });

  text += `[← मुख्य अनुक्रमणिका](${anukramanikaLink})\n`;
  fs.writeFileSync(filePath, text.trim() + '\n', 'utf8');
}

